CREATE TABLE procurement_requests(request_id text NOT NULL,version text NOT NULL,title text NOT NULL,category text NOT NULL,currency text NOT NULL,budget_minor bigint NOT NULL CHECK(budget_minor>0),decision_owner text NOT NULL,submission_deadline timestamptz NOT NULL,payload jsonb NOT NULL,evidence_boundary text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(request_id,version));
CREATE TABLE agent_plans(plan_fingerprint text PRIMARY KEY,request_id text NOT NULL,request_version text NOT NULL,payload jsonb NOT NULL,auto_award boolean NOT NULL DEFAULT false CHECK(auto_award=false),auto_purchase boolean NOT NULL DEFAULT false CHECK(auto_purchase=false),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE vendors(vendor_id text PRIMARY KEY,legal_name text NOT NULL,country text NOT NULL,domain text NOT NULL UNIQUE,restricted_party_status text NOT NULL,conflicts jsonb NOT NULL,synthetic boolean NOT NULL DEFAULT true,payload jsonb NOT NULL);
CREATE TABLE bids(bid_id text PRIMARY KEY,vendor_id text NOT NULL REFERENCES vendors(vendor_id),request_id text NOT NULL,request_version text NOT NULL,bid_fingerprint text NOT NULL UNIQUE,submitted_at timestamptz NOT NULL,currency text NOT NULL,tco_minor bigint NOT NULL,payload jsonb NOT NULL);
CREATE TABLE vendor_evidence(evidence_fingerprint text PRIMARY KEY,evidence_id text NOT NULL,vendor_id text NOT NULL REFERENCES vendors(vendor_id),evidence_type text NOT NULL,status text NOT NULL,confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1),observed_at timestamptz NOT NULL,source_url text NOT NULL,synthetic boolean NOT NULL DEFAULT true,payload jsonb NOT NULL,UNIQUE(vendor_id,evidence_id));
CREATE TABLE evaluation_reports(report_fingerprint text PRIMARY KEY,request_id text NOT NULL,request_version text NOT NULL,status text NOT NULL,recommended_vendor_id text,payload jsonb NOT NULL,auto_award boolean NOT NULL DEFAULT false CHECK(auto_award=false),auto_purchase boolean NOT NULL DEFAULT false CHECK(auto_purchase=false),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE decision_reviews(review_fingerprint text PRIMARY KEY,report_fingerprint text NOT NULL REFERENCES evaluation_reports(report_fingerprint),reviewer_id text NOT NULL,reviewer_role text NOT NULL,decision text NOT NULL,rationale text NOT NULL,award_authorized boolean NOT NULL DEFAULT false CHECK(award_authorized=false),purchase_authorized boolean NOT NULL DEFAULT false CHECK(purchase_authorized=false),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE award_packets(packet_fingerprint text PRIMARY KEY,report_fingerprint text NOT NULL REFERENCES evaluation_reports(report_fingerprint),vendor_id text NOT NULL,requires_authorized_buyer boolean NOT NULL DEFAULT true,award_authorized boolean NOT NULL DEFAULT false CHECK(award_authorized=false),purchase_authorized boolean NOT NULL DEFAULT false CHECK(purchase_authorized=false),payload jsonb NOT NULL);
CREATE TABLE purchase_order_drafts(draft_fingerprint text PRIMARY KEY,request_id text NOT NULL,vendor_id text NOT NULL,currency text NOT NULL,amount_minor bigint NOT NULL,status text NOT NULL DEFAULT 'draft',issued boolean NOT NULL DEFAULT false CHECK(issued=false),auto_issue boolean NOT NULL DEFAULT false CHECK(auto_issue=false),payload jsonb NOT NULL);
CREATE TABLE procurement_audit(event_hash text PRIMARY KEY,event_id text NOT NULL UNIQUE,request_id text NOT NULL,previous_hash text NOT NULL,actor_id text NOT NULL,actor_role text NOT NULL,event_type text NOT NULL,occurred_at timestamptz NOT NULL,payload jsonb NOT NULL);
CREATE TABLE procurement_dlq(job_id text PRIMARY KEY,attempts integer NOT NULL,reason text NOT NULL,auto_replay boolean NOT NULL DEFAULT false CHECK(auto_replay=false),created_at timestamptz NOT NULL DEFAULT now());
